SELECT 
FROM sys_async_task

    AND task_type = #{taskType}
    AND status = #{status}

ORDER BY id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM sys_async_task

    AND task_type = #{taskType}
    AND status = #{status}

SELECT 
FROM sys_async_task
WHERE status = 'RUNNING'
  AND update_time < #{staleBefore}
ORDER BY id
LIMIT #{limit}
